svg.script:
(function () {
  const items = Array.from(document.querySelectorAll('.item'));
  const highlight = document.getElementById('selection');
  const reduced = matchMedia('(prefers-reduced-motion: reduce)');
  let selected = 2, y = 175, target = 175, velocity = 0, frame = 0, previous = 0;
  function paint(stretch = 0) {
    const height = 56 * (1 + stretch), width = 153 * (1 - stretch * .18);
    highlight.setAttribute('x', 47 + (153 - width) / 2);
    highlight.setAttribute('y', y - (height - 56) / 2);
    highlight.setAttribute('width', width);
    highlight.setAttribute('height', height);
  }
  function settle() {
    cancelAnimationFrame(frame); frame = 0; previous = 0;
    y = target; velocity = 0; paint();
  }
  function tick(time) {
    let remaining = previous ? Math.min((time - previous) / 1000, .032) : 1 / 60;
    previous = time;
    while (remaining > 0) {
      const dt = Math.min(remaining, 1 / 120);
      velocity += ((target - y) * 340 - velocity * 27) * dt;
      y += velocity * dt;
      remaining -= dt;
    }
    paint(Math.min(.085, Math.abs(velocity) * .0002));
    if (Math.abs(target - y) < .015 && Math.abs(velocity) < .04) settle();
    else frame = requestAnimationFrame(tick);
  }
  function select(index, focus) {
    selected = index; target = Number(items[index].dataset.y);
    items.forEach((item, i) => {
      item.setAttribute('aria-checked', String(i === index));
      item.setAttribute('tabindex', i === index ? '0' : '-1');
    });
    if (focus) items[index].focus({preventScroll: true});
    if (reduced.matches) settle();
    else if (!frame && y !== target) { previous = 0; frame = requestAnimationFrame(tick); }
  }
  items.forEach((item, index) => {
    item.addEventListener('click', () => select(index, false));
    item.addEventListener('keydown', event => {
      let next;
      if (event.key === 'ArrowDown' || event.key === 'ArrowRight') next = (index + 1) % items.length;
      if (event.key === 'ArrowUp' || event.key === 'ArrowLeft') next = (index + items.length - 1) % items.length;
      if (event.key === 'Home') next = 0;
      if (event.key === 'End') next = items.length - 1;
      if (event.key === 'Enter' || event.key === ' ') next = index;
      if (next !== undefined) { event.preventDefault(); select(next, true); }
    });
  });
  reduced.addEventListener('change', () => { if (reduced.matches) settle(); });
})();
